/* Fade in and rise over the first 260px of scroll after the element's top enters the window
   (a fixed distance, so things in the first screen are already settled at load). Each step
   starts 40px later. Only where view timelines exist and motion is allowed. */
@supports (animation-timeline: view()) {
  @media (prefers-reduced-motion: no-preference) {
    .superpower-reveal {
      animation: superpower-reveal-in linear both;
      animation-timeline: view();
      animation-range: entry calc(var(--superpower-reveal-step, 0) * 40px) entry calc(260px + var(--superpower-reveal-step, 0) * 40px);
    }
  }
}

@keyframes superpower-reveal-in {
  from {
    opacity: 0;
    transform: translateY(var(--superpower-reveal-rise, 22px));
  }
  to {
    opacity: 1;
    transform: none;
  }
}

import type { CSSProperties, ElementType, ReactNode } from "react";
import { cn } from "@foundry/foundry-utils";
import "./superpower-reveal.css";

export interface SuperpowerRevealProps {
  children?: ReactNode;
  /** the element to render (div by default; li inside lists, tr in tables) */
  as?: ElementType;
  /** position in a staggered row: 0, 1, 2… each arrives a little later */
  step?: number;
  /** how far it rises, in px (22 for cards, 12 for table rows) */
  rise?: number;
  className?: string;
}

export function SuperpowerReveal({ children, as: Tag = "div", step = 0, rise = 22, className }: SuperpowerRevealProps) {
  return (
    <Tag
      className={cn("superpower-reveal", className)}
      style={{ "--superpower-reveal-step": step, "--superpower-reveal-rise": `${rise}px` } as CSSProperties}
    >
      {children}
    </Tag>
  );
}
